import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { authService } from '../services/api';
import { 
  User, Lock, Bell, 
  Save, AlertTriangle, LogOut, ShieldCheck
} from 'lucide-react';
import toast from 'react-hot-toast';

export default function SettingsPage() {
  const { user, logout, updateUser } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');

  const [profile, setProfile] = useState({
    full_name: user?.full_name || user?.fullName || '',
    email: user?.email || '',
    phone: user?.phone || '',
    farm_name: user?.farm_name || user?.farm?.name || ''
  });

  const [notificationSettings, setNotificationSettings] = useState({
    email_health_alerts: true,
    email_task_reminders: true,
    email_financial_reports: false,
    email_low_stock_alerts: true,
    sms_alerts: false
  });

  const [passwordForm, setPasswordForm] = useState({
    current_password: '',
    new_password: '',
    confirm_password: ''
  });

  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const [meRes, setRes] = await Promise.allSettled([
          authService.getMe(),
          authService.getSettings()
        ]);
        if (meRes.status === 'fulfilled' && meRes.value?.data?.user) {
          const u = meRes.value.data.user;
          setProfile({
            full_name: u.full_name || '',
            email: u.email || '',
            phone: u.phone || '',
            farm_name: u.farm_name || u.farm?.name || ''
          });
        }
        if (setRes.status === 'fulfilled' && setRes.value?.data?.settings) {
          setNotificationSettings(prev => ({ ...prev, ...setRes.value.data.settings }));
        }
      } catch (err) {
        console.error('Ayarlar yüklenirken hata:', err);
      }
    };
    fetchSettings();
  }, []);

  const handleProfileChange = (field, value) => {
    setProfile(prev => ({ ...prev, [field]: value }));
  };

  const handleNotificationChange = (field) => {
    setNotificationSettings(prev => ({
      ...prev,
      [field]: !prev[field]
    }));
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (!profile.full_name.trim()) {
      toast.error('Ad Soyad boş bırakılamaz');
      return;
    }

    setSaving(true);
    try {
      await authService.updateProfile({ 
        full_name: profile.full_name.trim(), 
        phone: profile.phone.trim() || null 
      });

      if (profile.farm_name?.trim()) {
        await authService.updateFarm({ name: profile.farm_name.trim() });
      }

      if (updateUser) {
        updateUser({
          full_name: profile.full_name.trim(),
          phone: profile.phone.trim() || null,
          farm_name: profile.farm_name.trim()
        });
      }

      toast.success('Profil ve çiftlik bilgileri başarıyla güncellendi');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Profil güncellenemedi');
    } finally {
      setSaving(false);
    }
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!passwordForm.current_password) {
      toast.error('Mevcut şifrenizi girin');
      return;
    }
    if (passwordForm.new_password.length < 8) {
      toast.error('Yeni şifre en az 8 karakter olmalıdır');
      return;
    }
    if (passwordForm.new_password !== passwordForm.confirm_password) {
      toast.error('Yeni şifreler birbiriyle eşleşmiyor');
      return;
    }

    setSaving(true);
    try {
      await authService.changePassword(passwordForm.current_password, passwordForm.new_password);
      toast.success('Şifre başarıyla değiştirildi');
      setPasswordForm({ current_password: '', new_password: '', confirm_password: '' });
    } catch (err) {
      toast.error(err.response?.data?.error || 'Şifre değiştirilemedi');
    } finally {
      setSaving(false);
    }
  };

  const handleSaveNotifications = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await authService.updateSettings(notificationSettings);
      toast.success('Bildirim tercihleri kaydedildi');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Bildirim ayarları kaydedilemedi');
    } finally {
      setSaving(false);
    }
  };

  const tabs = [
    { id: 'profile', label: 'Profil', icon: User },
    { id: 'security', label: 'Güvenlik', icon: Lock },
    { id: 'notifications', label: 'Bildirimler', icon: Bell },
  ];

  const notificationLabels = {
    email_health_alerts: 'Sağlık Uyarıları',
    email_task_reminders: 'Görev Hatırlatıcıları',
    email_financial_reports: 'Finansal Raporlar',
    email_low_stock_alerts: 'Stok Uyarıları',
    sms_alerts: 'SMS Bildirimleri'
  };

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">⚙️ Ayarlar</h1>
          <p className="text-sm text-gray-500">Hesap bilgileri, çiftlik detayları ve güvenlik tercihleri</p>
        </div>
      </div>

      <div className="card p-0 overflow-hidden shadow-2xl shadow-blue-900/10">
        <div className="flex overflow-x-auto border-b bg-gray-50/50 scrollbar-hide">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-8 py-5 text-sm font-black uppercase tracking-widest whitespace-nowrap transition-all border-b-2 ${
                activeTab === tab.id
                  ? 'text-blue-600 border-blue-600 bg-white'
                  : 'text-gray-400 border-transparent hover:text-gray-600'
              }`}
            >
              <tab.icon className={`w-4 h-4 ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-400'}`} />
              {tab.label}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          {activeTab === 'profile' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
              <div className="flex flex-col sm:flex-row items-center gap-6 pb-8 border-b">
                <div className="w-24 h-24 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-3xl flex items-center justify-center text-4xl font-black text-white shadow-2xl shadow-blue-600/30 rotate-3 hover:rotate-0 transition-transform cursor-default">
                  {profile.full_name?.charAt(0)?.toUpperCase() || 'U'}
                </div>
                <div className="text-center sm:text-left">
                  <h3 className="text-2xl font-black text-gray-900">{profile.full_name || 'Kullanıcı'}</h3>
                  <p className="text-gray-500 font-medium">{profile.email || 'email@ornek.com'}</p>
                  <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2 mt-2">
                    <span className="px-3 py-1 bg-blue-50 text-blue-600 text-[10px] font-black uppercase tracking-widest rounded-lg border border-blue-100">
                      Çiftlik Yöneticisi
                    </span>
                    {profile.farm_name && (
                      <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black uppercase tracking-widest rounded-lg border border-green-100">
                        🏡 {profile.farm_name}
                      </span>
                    )}
                  </div>
                </div>
              </div>

              <form onSubmit={handleSaveProfile} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Ad Soyad</label>
                  <input 
                    type="text" 
                    value={profile.full_name} 
                    onChange={e => handleProfileChange('full_name', e.target.value)} 
                    className="input-field py-3 font-bold" 
                    required 
                  />
                </div>
                <div className="space-y-2">
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">
                    E-Posta Adresi <span className="text-[10px] text-gray-400 normal-case">(Değiştirilemez)</span>
                  </label>
                  <input 
                    type="email" 
                    value={profile.email} 
                    disabled 
                    title="E-posta adresi güvenlik nedeniyle değiştirilemez"
                    className="input-field py-3 font-bold bg-gray-100 text-gray-500 cursor-not-allowed" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Telefon Numarası</label>
                  <input 
                    type="tel" 
                    placeholder="05xx xxx xx xx"
                    value={profile.phone} 
                    onChange={e => handleProfileChange('phone', e.target.value)} 
                    className="input-field py-3 font-bold" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Çiftlik Adı</label>
                  <input 
                    type="text" 
                    placeholder="Örn: Anadolu Çiftliği"
                    value={profile.farm_name} 
                    onChange={e => handleProfileChange('farm_name', e.target.value)} 
                    className="input-field py-3 font-bold" 
                  />
                </div>
                <div className="md:col-span-2 pt-4">
                  <button type="submit" disabled={saving} className="btn-primary w-full py-4 flex items-center justify-center gap-2 shadow-lg shadow-blue-600/20">
                    <Save className="w-5 h-5" />
                    {saving ? 'Kaydediliyor...' : 'Profil Bilgilerini Güncelle'}
                  </button>
                </div>
              </form>
            </div>
          )}

          {activeTab === 'security' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
              <div className="rounded-3xl p-6 bg-amber-50 border border-amber-100 flex items-start gap-4">
                <div className="p-3 bg-amber-500 rounded-2xl text-white shadow-lg shadow-amber-500/20">
                  <Lock className="w-6 h-6" />
                </div>
                <div>
                  <h4 className="font-black text-amber-900 uppercase tracking-tight">Hesap Güvenliği</h4>
                  <p className="text-amber-700 text-sm font-medium mt-1">
                    Şifrenizi düzenli aralıklarla değiştirmeniz hesabınızı güvende tutar. Yeni şifreniz en az 8 karakter uzunluğunda olmalıdır.
                  </p>
                </div>
              </div>

              <form onSubmit={handleChangePassword} className="space-y-6">
                <div className="space-y-2">
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Mevcut Şifre</label>
                  <input 
                    type="password" 
                    placeholder="Mevcut parolanız"
                    value={passwordForm.current_password} 
                    onChange={e => setPasswordForm({ ...passwordForm, current_password: e.target.value })} 
                    className="input-field py-3" 
                    required 
                  />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Yeni Şifre (En az 8 karakter)</label>
                    <input 
                      type="password" 
                      placeholder="Yeni şifreniz"
                      value={passwordForm.new_password} 
                      onChange={e => setPasswordForm({ ...passwordForm, new_password: e.target.value })} 
                      className="input-field py-3" 
                      required 
                      minLength={8} 
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="block text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Yeni Şifre (Tekrar)</label>
                    <input 
                      type="password" 
                      placeholder="Yeni şifrenizi doğrulayın"
                      value={passwordForm.confirm_password} 
                      onChange={e => setPasswordForm({ ...passwordForm, confirm_password: e.target.value })} 
                      className="input-field py-3" 
                      required 
                      minLength={8}
                    />
                  </div>
                </div>
                <button type="submit" disabled={saving} className="btn-primary w-full py-4 flex items-center justify-center gap-2 bg-gradient-to-r from-gray-800 to-black hover:from-black hover:to-gray-800 shadow-xl">
                  <ShieldCheck className="w-5 h-5" />
                  {saving ? 'Değiştiriliyor...' : 'Şifreyi Güvenle Güncelle'}
                </button>
              </form>
            </div>
          )}

          {activeTab === 'notifications' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-top-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {Object.entries(notificationSettings).map(([key, value]) => (
                  <label key={key} className={`flex items-center justify-between p-5 rounded-3xl cursor-pointer transition-all border-2 ${value ? 'bg-blue-50 border-blue-600 shadow-lg shadow-blue-600/10' : 'bg-white border-gray-100 hover:border-blue-200'}`}>
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-colors ${value ? 'bg-blue-600 text-white' : 'bg-gray-50 text-gray-400'}`}>
                        <Bell className="w-5 h-5" />
                      </div>
                      <span className={`font-black uppercase tracking-tighter text-sm ${value ? 'text-blue-900' : 'text-gray-400'}`}>
                        {notificationLabels[key] || key}
                      </span>
                    </div>
                    <input type="checkbox" checked={value} onChange={() => handleNotificationChange(key)} className="sr-only" />
                    <div className={`w-12 h-6 rounded-full relative transition-colors ${value ? 'bg-blue-600' : 'bg-gray-200'}`}>
                      <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${value ? 'left-7' : 'left-1'}`} />
                    </div>
                  </label>
                ))}
              </div>
              <button onClick={handleSaveNotifications} disabled={saving} className="btn-primary w-full py-4 flex items-center justify-center gap-2">
                <Save className="w-5 h-5" />
                {saving ? 'Kaydediliyor...' : 'Bildirim Tercihlerini Kaydet'}
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="card p-0 overflow-hidden border-2 border-red-500/30 bg-red-50/20">
        <div className="px-6 py-4 bg-red-500/10 border-b border-red-500/20 flex items-center gap-2">
          <AlertTriangle className="w-5 h-5 text-red-600" />
          <h3 className="text-lg font-black text-red-900 uppercase tracking-tight">Kritik İşlemler</h3>
        </div>
        <div className="p-8">
          <p className="text-sm text-red-700 font-medium mb-6">Aşağıdaki işlemler geri alınamaz ve tüm verilerinizin kalıcı olarak silinmesine neden olabilir. Lütfen dikkatli ilerleyin.</p>
          <div className="flex flex-col sm:flex-row gap-4">
            <button 
              onClick={async () => {
                if (!window.confirm('Hesabınızı ve çiftliğinizi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz!')) return;
                try {
                  await authService.deleteAccount();
                  toast.success('Hesabınız başarıyla silindi');
                  logout();
                } catch (err) {
                  toast.error(err.response?.data?.error || 'Hesap silinemedi');
                }
              }} 
              className="flex-1 px-6 py-4 bg-white border-2 border-red-200 text-red-600 font-black uppercase tracking-widest text-xs rounded-2xl hover:bg-red-600 hover:text-white hover:border-red-600 transition-all shadow-sm"
            >
              Hesabı / Çiftliği Kalıcı Olarak Sil
            </button>
            <button 
              onClick={() => window.confirm('Oturumu kapatmak istediğinizden emin misiniz?') && logout()} 
              className="flex-1 px-6 py-4 bg-orange-600 text-white font-black uppercase tracking-widest text-xs rounded-2xl hover:bg-orange-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-orange-600/20"
            >
              <LogOut className="w-4 h-4" />
              Oturumu Güvenli Kapat
            </button>
          </div>
        </div>
      </div>

      <div className="text-center pb-10">
        <p className="text-xs text-gray-400 font-medium">mFk Farm Sistem © 2026 Tüm hakları saklıdır. • Lisanslı Çiftlik Sürümü</p>
      </div>
    </div>
  );
}